const CSS = `:root{--bg:#f7f2e8;--paper:#fffdf8;--ink:#1b2722;--mute:#5d6a63;--line:#e4dccb;--teal:#0e6f66;--teal2:#0a5650;--gold:#c08a2b;--card:#fffdf8;--shadow:0 1px 2px rgba(27,39,34,.06),0 6px 24px rgba(27,39,34,.06)}
@media (prefers-color-scheme:dark){:root{--bg:#111815;--paper:#18211d;--ink:#ece6d8;--mute:#a3ada6;--line:#2a3530;--teal:#4fb3a6;--teal2:#7fd0c4;--gold:#e0ad55;--card:#18211d;--shadow:none}}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
a{color:var(--teal)}img{max-width:100%;display:block}
.w{max-width:1120px;margin:0 auto;padding:0 16px}
.net{background:var(--ink);color:var(--bg);font-size:13px}.net .w{display:flex;gap:14px;align-items:center;min-height:34px;flex-wrap:wrap}.net a{color:inherit;text-decoration:none;opacity:.8}.net a:hover{opacity:1}.net b{opacity:1}.net .sp{flex:1}
header.top{background:var(--paper);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:1000}
header.top .w{display:flex;align-items:center;gap:16px;min-height:64px}
.logo{font-family:Fraunces,Georgia,serif;font-weight:700;font-size:24px;color:var(--ink);text-decoration:none;letter-spacing:-.01em;white-space:nowrap}.logo span{color:var(--teal)}
nav.main{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none;flex:1}nav.main::-webkit-scrollbar{display:none}
nav.main a{padding:10px 12px;border-radius:999px;text-decoration:none;color:var(--ink);font-size:15px;white-space:nowrap}nav.main a:hover,nav.main a.on{background:var(--bg)}
select.lang{font:inherit;font-size:14px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink)}
.hero{position:relative;color:#fff;background:#0b3b37}.hero img{width:100%;height:min(62vh,560px);object-fit:cover;opacity:.75}
.hero .in{position:absolute;inset:auto 0 0 0;padding:32px 0;background:linear-gradient(transparent,rgba(0,0,0,.65))}
.hero h1{font-family:Fraunces,Georgia,serif;font-size:clamp(32px,5.5vw,60px);line-height:1.05;margin:0 0 12px;max-width:16ch;letter-spacing:-.02em}
.hero p{max-width:60ch;margin:0 0 18px;font-size:18px;opacity:.95}
.btn{display:inline-block;padding:12px 18px;border-radius:999px;background:var(--teal);color:#fff;text-decoration:none;font-weight:600;margin:0 8px 8px 0}.btn.alt{background:rgba(255,255,255,.15);backdrop-filter:blur(4px);border:1px solid rgba(255,255,255,.4)}
section{padding:40px 0}h2.sec{font-family:Fraunces,Georgia,serif;font-size:clamp(26px,3.2vw,36px);margin:0 0 6px;letter-spacing:-.01em}.lead{color:var(--mute);margin:0 0 22px;max-width:70ch}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden;text-decoration:none;color:inherit;box-shadow:var(--shadow);display:flex;flex-direction:column;transition:transform .15s}.card:hover{transform:translateY(-2px)}
.card .ph{aspect-ratio:16/10;background:linear-gradient(135deg,var(--c,#0e7c86),#1b2722);position:relative;display:flex;align-items:flex-end;padding:12px;color:#fff}.card .ph img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.card .ph .k{position:relative;font-size:12px;letter-spacing:.08em;text-transform:uppercase;background:rgba(0,0,0,.45);padding:3px 8px;border-radius:999px}
.badge{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#2a1c00;background:var(--gold);padding:3px 8px;border-radius:999px}
.card .ph .badge{position:absolute;top:10px;right:10px}
.card .tx{padding:14px 16px 16px}.card h3{font-family:Fraunces,Georgia,serif;font-size:21px;margin:0 0 4px;line-height:1.2}.card .rg{font-size:13px;color:var(--mute);margin:0 0 6px}.card p{margin:0;font-size:15px;color:var(--mute)}
.wx{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}.wxc{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px 16px}.wxc h3{margin:0;font-size:15px}.wxc .t{font-size:34px;font-weight:700;font-family:Fraunces,Georgia,serif}.wxc .s{color:var(--mute);font-size:14px}
.days{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-top:10px;font-size:12px;text-align:center}.days div{background:var(--bg);border-radius:8px;padding:6px 2px}.days b{display:block;font-size:13px}
#map{height:min(70vh,620px);border-radius:14px;border:1px solid var(--line);z-index:1}.mapsm{height:300px}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 14px}.chip{border:1px solid var(--line);background:var(--paper);color:var(--ink);padding:8px 14px;border-radius:999px;font:inherit;font-size:14px;cursor:pointer}.chip.on{background:var(--ink);color:var(--bg);border-color:var(--ink)}
article.pl{max-width:760px;margin:0 auto}article.pl h1{font-family:Fraunces,Georgia,serif;font-size:clamp(32px,5vw,50px);line-height:1.08;margin:12px 0 8px;letter-spacing:-.02em}
.crumbs{font-size:14px;color:var(--mute);padding-top:20px}.crumbs a{color:var(--mute)}
.fig{margin:18px 0}.fig img{border-radius:14px;width:100%;aspect-ratio:16/9;object-fit:cover}.fig figcaption{font-size:13px;color:var(--mute);margin-top:6px}
.nofig{aspect-ratio:16/7;border-radius:14px;background:linear-gradient(135deg,var(--c,#0e7c86),#1b2722);display:flex;align-items:center;justify-content:center;color:#fff;opacity:.9;margin:18px 0}
.body{font-size:18px}.body h2{font-family:Fraunces,Georgia,serif;font-size:26px;margin:28px 0 8px}
.tipb{background:var(--paper);border:1px solid var(--line);border-left:4px solid var(--gold);border-radius:10px;padding:14px 16px;margin:18px 0}.tipb b{display:block;margin-bottom:4px}
.news{display:grid;gap:12px}.news a.n{display:block;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px;text-decoration:none;color:inherit}.news a.n b{font-family:Fraunces,Georgia,serif;font-size:19px;display:block;line-height:1.25}.news a.n span{color:var(--mute);font-size:14px}
.band{background:var(--paper);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
footer{padding:36px 0;color:var(--mute);font-size:14px;border-top:1px solid var(--line);margin-top:30px}footer a{color:var(--mute)}
.two{display:grid;grid-template-columns:1.4fr 1fr;gap:28px}@media(max-width:820px){.two{grid-template-columns:1fr}.hero p{font-size:16px}header.top .w{flex-wrap:wrap;gap:6px 10px;padding-top:8px}.logo{font-size:21px;flex:1}nav.main{order:3;flex-basis:100%;margin:0 -16px;padding:0 12px 6px}.net .d{display:none}.net .w{gap:10px;flex-wrap:nowrap;overflow-x:auto;white-space:nowrap}}
.h1{font-family:Fraunces,Georgia,serif;font-size:clamp(30px,4vw,46px);margin:6px 0 4px;letter-spacing:-.02em}.h2s{font-size:24px!important;margin-top:28px!important}.gal{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:18px 0}.gal figure{margin:0}.gal figure:first-child{grid-column:1/-1}.gal img{border-radius:12px;width:100%;aspect-ratio:3/2;object-fit:cover}.gal figure:first-child img{aspect-ratio:16/9}.gal figcaption{font-size:12px;color:var(--mute);margin-top:4px}.faq details{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:8px 0}.faq summary{font-weight:600;cursor:pointer}.faq p{margin:8px 0 0}.acts .btn{margin-bottom:8px}.btn.alt2{background:var(--paper);color:var(--ink);border:1px solid var(--line)}.upd{color:var(--mute);font-size:14px;margin-top:28px}.itin ol{margin:8px 0 0;padding-left:20px}.itin li{margin:4px 0}a.chip{text-decoration:none;display:inline-block}.ico{font-size:18px;text-decoration:none;padding:6px}.nl{background:var(--ink);color:var(--bg);padding:32px 0}.nl h2{font-family:Fraunces,Georgia,serif;margin:0 0 6px}.nl form,.tipf{display:flex;gap:8px;flex-wrap:wrap}.nl input,.tipf input,.tipf textarea{flex:1;min-width:200px;padding:12px;border-radius:10px;border:1px solid var(--line);font:inherit}.tipf{flex-direction:column}.tipf textarea{min-height:90px}.nl .btn{border:0;cursor:pointer}.srch input{width:100%;font:inherit;font-size:18px;padding:14px;border-radius:12px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}button.btn{border:0;cursor:pointer;font:inherit;font-weight:600}@media print{.net,header.top,footer,.nl,.noprint,#map,.acts,.tipb+form{display:none!important}body{background:#fff}}.leaflet-popup-content a{font-weight:600}.leaflet-popup-content{font:14px/1.45 Inter,system-ui,sans-serif}details.lp{position:relative}details.lp summary{list-style:none;display:flex;align-items:center;gap:7px;cursor:pointer;padding:7px 11px;border:1px solid var(--line);border-radius:999px;background:var(--paper);color:var(--ink);font-size:14px;user-select:none}details.lp summary::-webkit-details-marker{display:none}details.lp summary i{font-style:normal;font-size:11px;opacity:.7;transition:transform .2s}details.lp[open] summary i{transform:rotate(180deg)}img.fl{border-radius:3px;box-shadow:0 0 0 1px rgba(0,0,0,.12);object-fit:cover;flex:none}.lp-m{position:absolute;right:0;top:calc(100% + 8px);z-index:3000;background:var(--paper);border:1px solid var(--line);border-radius:16px;box-shadow:0 18px 50px rgba(0,0,0,.22);padding:10px;display:grid;grid-template-columns:repeat(2,minmax(150px,1fr));gap:4px;animation:lpin .18s ease}@keyframes lpin{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}.lp-m a{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:10px;color:var(--ink);text-decoration:none;font-size:15px}.lp-m a:hover{background:rgba(14,111,102,.09)}.lp-m a.on{background:rgba(14,111,102,.14);font-weight:700}header.top.over details.lp summary{background:rgba(255,255,255,.15);color:#fff;border-color:rgba(255,255,255,.4);backdrop-filter:blur(6px)}header.top.over.solid details.lp summary{background:var(--paper);color:var(--ink);border-color:var(--line)}.lgw{pointer-events:auto;padding:4px}.lgw details.lp summary{border:0;background:transparent}.lsug{position:fixed;left:20px;bottom:22px;z-index:4000;display:flex;align-items:center;gap:6px;background:var(--ink);color:#fff;border-radius:999px;padding:6px 6px 6px 16px;box-shadow:0 10px 30px rgba(0,0,0,.3);animation:lpin .3s ease}.lsug a{color:#fff;text-decoration:none;font-weight:700;display:flex;align-items:center;gap:8px}.lsug button{border:0;background:rgba(255,255,255,.15);color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:18px}.lp-m a span{white-space:nowrap}.bnav{display:none}@media(max-width:820px){.lp-m{position:fixed;left:12px;right:12px;top:auto;bottom:84px;grid-template-columns:repeat(2,1fr)}details.lp summary{padding:5px 9px;font-size:13px}.bnav{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:2500;background:rgba(255,253,248,.97);backdrop-filter:blur(10px);border-top:1px solid var(--line);padding:6px 4px calc(6px + env(safe-area-inset-bottom))}.bnav a{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:1px;color:var(--ink);text-decoration:none;padding:4px 2px;border-radius:10px}.bnav a span{font-size:20px;line-height:1.1}.bnav a small{font-size:10.5px;letter-spacing:-.1px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bnav a.on{color:var(--teal);font-weight:700;background:rgba(14,111,102,.08)}body{padding-bottom:72px}nav.main{-webkit-mask-image:linear-gradient(90deg,#000 82%,transparent);mask-image:linear-gradient(90deg,#000 82%,transparent)}.fab-map{display:none}.totop{bottom:86px}.lsug{bottom:86px;max-width:calc(100% - 24px)}}@media(prefers-color-scheme:dark){.bnav{background:rgba(20,26,24,.96)}}.hx-rot,.hx-in h1,.hx-d{text-shadow:0 2px 18px rgba(0,0,0,.45)}.hx-q{display:flex;max-width:560px;margin:4px 0 18px;background:rgba(255,255,255,.96);border-radius:999px;padding:5px;box-shadow:0 10px 30px rgba(0,0,0,.25)}.hx-q input{flex:1;min-width:0;border:0;background:transparent;font:inherit;font-size:16px;padding:10px 16px;color:#1b2722;outline:none}.hx-q button{border:0;border-radius:999px;background:var(--teal);color:#fff;font:inherit;font-weight:700;padding:10px 20px;cursor:pointer}.hx-cap{position:absolute;right:24px;bottom:72px;color:#fff;font-size:13px;text-decoration:none;background:rgba(0,0,0,.35);backdrop-filter:blur(6px);padding:6px 12px;border-radius:999px;z-index:3}.hx-dots{position:absolute;right:24px;bottom:110px;display:flex;gap:6px;z-index:3}.hx-dots i{width:9px;height:9px;border-radius:9px;background:rgba(255,255,255,.45);cursor:pointer;transition:width .3s}.hx-dots i.on{width:26px;background:#fff}body.home .fab-map{opacity:0;pointer-events:none;transform:translateY(12px);transition:opacity .3s,transform .3s}body.home.scr .fab-map{opacity:1;pointer-events:auto;transform:none}@media(max-width:820px){header.top select.lang{max-width:96px;padding:4px 6px;font-size:13px}header.top .w{flex-wrap:wrap}.hx-cap,.hx-dots{display:none}.hx-q{margin:0 0 14px}.hx-q button{padding:10px 14px}}
:root{--sun:#e86f4d;--sand:#efe4cf}
body{font-size:16.5px}.kick{font-size:13px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:#f5d9a6;margin:0 0 10px}.kick.dark{color:var(--teal)}
.sec.xl{font-size:clamp(30px,4.4vw,52px);line-height:1.05;letter-spacing:-.02em}.center{text-align:center}
header.top.over{position:absolute;top:34px;left:0;right:0;background:transparent;border-color:transparent;transition:background .3s,box-shadow .3s}header.top.over .logo,header.top.over nav.main a,header.top.over .ico{color:#fff}header.top.over nav.main a:hover,header.top.over nav.main a.on{background:rgba(255,255,255,.15)}
header.top.over.solid{position:fixed;top:0;background:var(--paper);box-shadow:0 2px 20px rgba(0,0,0,.08)}header.top.over.solid .logo,header.top.over.solid nav.main a,header.top.over.solid .ico{color:var(--ink)}header.top.over.solid .logo span{color:var(--teal)}header.top.over .logo span{color:#f5d9a6}
header.top.over select.lang{background:rgba(255,255,255,.15);color:#fff;border-color:rgba(255,255,255,.4)}header.top.over.solid select.lang{background:var(--paper);color:var(--ink);border-color:var(--line)}
.net{position:relative;z-index:1001}
.hx{position:relative;height:100svh;min-height:560px;color:#fff;overflow:hidden;background:#0b3b37}.hx-sl img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transform:scale(1.08);transition:opacity 1.6s ease,transform 8s linear}.hx-sl img.on{opacity:1;transform:scale(1)}
.hx-sh{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.45) 0%,rgba(0,0,0,.05) 35%,rgba(0,0,0,.25) 60%,rgba(0,0,0,.78) 100%)}
.hx-in{position:absolute;left:0;right:0;bottom:120px}.hx h1{font-family:Fraunces,Georgia,serif;font-size:clamp(42px,7.5vw,96px);line-height:.98;letter-spacing:-.03em;margin:0 0 8px;max-width:13ch;text-shadow:0 2px 30px rgba(0,0,0,.35)}
.hx-rot{font-family:Fraunces,Georgia,serif;font-size:clamp(22px,3vw,34px);margin:0 0 14px;color:#f5d9a6}.hx-rot span{transition:opacity .35s;display:inline-block}.hx-d{max-width:56ch;font-size:18px;opacity:.95;margin:0 0 22px}
.btn.big{padding:15px 24px;font-size:17px;background:var(--sun)}.btn.big:hover{filter:brightness(1.08)}.btn.ghost{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.55);backdrop-filter:blur(6px);color:#fff}
.hx-live{position:absolute;left:0;right:0;bottom:28px;display:flex;gap:22px;flex-wrap:wrap;font-size:14px;opacity:.95}.hx-live span{background:rgba(0,0,0,.28);backdrop-filter:blur(6px);padding:7px 12px;border-radius:999px}
.hx-sc{position:absolute;right:24px;bottom:26px;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;color:#fff;text-decoration:none;border:1px solid rgba(255,255,255,.6);animation:bob 2s infinite}@keyframes bob{50%{transform:translateY(6px)}}
.exp{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.ex{position:relative;border-radius:18px;overflow:hidden;aspect-ratio:3/4;color:#fff;text-decoration:none;box-shadow:var(--shadow)}.ex img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.ex:hover img{transform:scale(1.07)}
.ex::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 45%,rgba(0,0,0,.75))}.ex-t{position:absolute;left:16px;right:16px;bottom:14px;z-index:1}.ex-t b{display:block;font-family:Fraunces,Georgia,serif;font-size:22px}.ex-t small{opacity:.85}
.sod{background:linear-gradient(135deg,#0b3b37,#12524b);color:#fff}.sod-in{display:grid;grid-template-columns:1.1fr 1fr;gap:40px;align-items:center}.sod-ph img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:20px;box-shadow:0 20px 60px rgba(0,0,0,.35)}
.sod h2{font-family:Fraunces,Georgia,serif;font-size:clamp(32px,4vw,50px);margin:0 0 6px;line-height:1.05}.sod .rg{opacity:.8}.tipline{background:rgba(255,255,255,.08);border-left:3px solid #f5d9a6;padding:10px 14px;border-radius:8px}
.hd{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap}.more{font-weight:700;text-decoration:none;white-space:nowrap}
.mos{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:220px;gap:12px}.mo{position:relative;border-radius:16px;overflow:hidden;color:#fff;text-decoration:none}.mo.big{grid-column:span 2;grid-row:span 2}.mo img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.mo:hover img{transform:scale(1.06)}
.mo::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 50%,rgba(0,0,0,.72))}.mo span{position:absolute;left:14px;right:14px;bottom:12px;z-index:1}.mo b{display:block;font-family:Fraunces,Georgia,serif;font-size:21px}.mo.big b{font-size:34px}.mo small{opacity:.85;font-size:12px;text-transform:uppercase;letter-spacing:.08em}
.why{background:var(--sand)}.why3{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin-top:20px}.why3 div{background:var(--paper);border-radius:18px;padding:26px;box-shadow:var(--shadow)}.wi{font-size:38px}.why3 h3{font-family:Fraunces,Georgia,serif;font-size:24px;margin:8px 0 6px}.why3 p{margin:0;color:var(--mute)}
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:18px 0 26px}.steps div{border-top:3px solid var(--sun);padding-top:12px}.steps span{font-family:Fraunces,Georgia,serif;font-size:34px;color:var(--sun);font-weight:700}.steps b{display:block;font-size:18px}.steps p{margin:4px 0 0;color:var(--mute)}
.itc{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.it2{position:relative;border-radius:18px;overflow:hidden;aspect-ratio:4/5;color:#fff;text-decoration:none}.it2 img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.it2:hover img{transform:scale(1.06)}.it2::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 40%,rgba(0,0,0,.8))}
.dn{position:absolute;top:14px;left:14px;z-index:1;background:var(--sun);padding:6px 12px;border-radius:999px;font-weight:700;font-size:14px}.it2-t{position:absolute;left:16px;right:16px;bottom:16px;z-index:1}.it2-t b{display:block;font-family:Fraunces,Georgia,serif;font-size:24px;line-height:1.1}.it2-t small{opacity:.9}
section.dark{background:#0f1714;color:#ece6d8}section.dark .lead{color:#a9b3ac}.vids{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.vids.one{grid-template-columns:1fr;max-width:760px}
.yt{position:relative;border:0;padding:0;border-radius:14px;overflow:hidden;cursor:pointer;aspect-ratio:16/9;background:#000;display:block;width:100%}.yt img{width:100%;height:100%;object-fit:cover;opacity:.85;transition:opacity .3s}.yt:hover img{opacity:1}
.yp{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:64px;height:64px;border-radius:50%;background:rgba(232,111,77,.95);color:#fff;display:grid;place-items:center;font-size:24px}.yc{position:absolute;left:10px;right:10px;bottom:8px;color:#fff;font-size:12px;text-align:left;text-shadow:0 1px 4px #000}.yt iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.regs{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.rg2{position:relative;border-radius:18px;overflow:hidden;aspect-ratio:1;color:#fff;text-decoration:none}.rg2 img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.rg2:hover img{transform:scale(1.06)}.rg2::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 45%,rgba(0,0,0,.75))}.rg2 span{position:absolute;left:16px;bottom:14px;z-index:1}.rg2 b{display:block;font-family:Fraunces,Georgia,serif;font-size:24px}
.mapcta{background:linear-gradient(120deg,#0e6f66,#0b3b37);color:#fff}.mapcta-in{display:grid;grid-template-columns:1fr 1.1fr;gap:36px;align-items:center}.mapcta h2{font-family:Fraunces,Georgia,serif;font-size:clamp(28px,3.6vw,44px);margin:0 0 8px}.mapcta-img img{width:100%;border-radius:18px;box-shadow:0 20px 60px rgba(0,0,0,.35)}
.nums{background:var(--sand)}.nm{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;text-align:center}.nm b{display:block;font-family:Fraunces,Georgia,serif;font-size:clamp(44px,6vw,72px);color:var(--teal);line-height:1}.nm span{color:var(--mute)}
.ph-hero{position:relative;height:78svh;min-height:480px;max-height:760px;color:#fff;overflow:hidden;background:#0b3b37}@media(max-width:700px){.ph-hero{height:62svh;min-height:400px}}.ph-hero.short{height:56svh;min-height:380px}.ph-hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ph-in{position:absolute;left:0;right:0;bottom:44px}.ph-hero h1{font-family:Fraunces,Georgia,serif;font-size:clamp(40px,6.5vw,84px);line-height:1;letter-spacing:-.03em;margin:10px 0 8px;text-shadow:0 2px 30px rgba(0,0,0,.35)}.ph-sub{font-size:19px;max-width:60ch;opacity:.95;margin:0 0 16px}.ph-cr{position:absolute;right:12px;bottom:8px;font-size:11px;opacity:.75;margin:0}
.crumbs.light,.crumbs.light a{color:rgba(255,255,255,.85)}
.pl2{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:40px;padding-top:34px;padding-bottom:30px}.pl2-side{position:relative}.pl2-side .qf{position:static;background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:18px;margin-bottom:16px;box-shadow:var(--shadow)}.pl2-side .qf:first-child{position:sticky;top:84px}
.qf h2{font-family:Fraunces,Georgia,serif;font-size:21px;margin:0 0 10px}.qf dl{display:grid;grid-template-columns:auto 1fr;gap:8px 14px;margin:0 0 12px;font-size:15px}.qf dt{color:var(--mute)}.qf dd{margin:0;font-weight:600}.cp{border:0;background:none;font:inherit;font-weight:600;color:var(--teal);cursor:pointer;padding:0}
.qf .acts .btn{margin:4px 4px 0 0;padding:10px 14px;font-size:14px}.lead1 p{font-size:21px;line-height:1.55;font-family:Fraunces,Georgia,serif;font-weight:400}
.gal2{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.gal2 button{border:0;padding:0;border-radius:12px;overflow:hidden;cursor:zoom-in;background:none}.gal2 img{width:100%;aspect-ratio:3/2;object-fit:cover;transition:transform .4s}.gal2 button:hover img{transform:scale(1.05)}.crs{font-size:12px;color:var(--mute)}
.hs{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(260px,1fr);gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:8px}.hs>*{scroll-snap-align:start}
.pn{display:flex;justify-content:space-between;gap:12px;margin-top:20px;font-weight:600}.pn a{text-decoration:none}
.lb{position:fixed;inset:0;z-index:3000;background:rgba(0,0,0,.92);display:flex;align-items:center;justify-content:center}.lb[hidden]{display:none}.lb img{max-width:92vw;max-height:84vh;border-radius:8px}.lb button{position:absolute;border:0;background:rgba(255,255,255,.12);color:#fff;font-size:34px;width:52px;height:52px;border-radius:50%;cursor:pointer}.lb-x{top:16px;right:16px}.lb-p{left:16px}.lb-n{right:16px}.lb-c{position:absolute;bottom:14px;color:#ddd;font-size:13px;margin:0}
.fab-map{position:fixed;right:18px;bottom:18px;z-index:1500;background:var(--ink);color:var(--bg);text-decoration:none;border-radius:999px;padding:12px 18px;font-weight:700;box-shadow:0 8px 24px rgba(0,0,0,.25)}.fab-map:hover{background:var(--teal);color:#fff}
.totop{position:fixed;right:18px;bottom:76px;z-index:1500;width:44px;height:44px;border-radius:50%;border:0;background:var(--paper);box-shadow:0 6px 18px rgba(0,0,0,.18);font-size:18px;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .3s}.totop.show{opacity:1;pointer-events:auto}
.rv{opacity:0;transform:translateY(26px);transition:opacity .8s ease,transform .8s ease}.rv.in{opacity:1;transform:none}
/* 13-nov-2026: buttons, focus, Mamboro top 10 */
.btn{display:inline-flex;align-items:center;gap:8px;min-height:44px;line-height:1.2;border:0;cursor:pointer;font:inherit;font-weight:700;letter-spacing:.005em;box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -8px rgba(14,111,102,.75);transition:transform .15s ease,box-shadow .2s ease,filter .2s ease,background .2s ease}
.btn:hover{transform:translateY(-2px);filter:brightness(1.06);box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 12px 26px -10px rgba(14,111,102,.85)}.btn:active{transform:translateY(0) scale(.98)}
.btn.alt2{box-shadow:0 1px 2px rgba(0,0,0,.06)}.btn.alt2:hover{background:var(--bg);box-shadow:0 8px 20px -12px rgba(0,0,0,.35)}
.btn.big{box-shadow:0 10px 30px -10px rgba(232,111,77,.9)}.btn.ghost{box-shadow:none}
a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible,select:focus-visible{outline:3px solid #e0ad55;outline-offset:3px;border-radius:10px}
.chip{transition:background .2s,color .2s,border-color .2s,transform .15s}.chip:hover{border-color:var(--teal);transform:translateY(-1px)}
.card{transition:transform .2s ease,box-shadow .25s ease}.card:hover{transform:translateY(-4px);box-shadow:0 18px 40px -18px rgba(27,39,34,.45)}
.fab-map{display:inline-flex;align-items:center;gap:6px;transition:transform .15s,background .2s}.fab-map:hover{transform:translateY(-2px)}
.near{background:linear-gradient(180deg,var(--bg),var(--sand))}
.ncs{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(210px,1fr);gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;padding:4px 2px 14px;scrollbar-width:thin}.ncs>a{scroll-snap-align:start}
.nc{display:flex;flex-direction:column;border-radius:18px;overflow:hidden;background:var(--card);border:1px solid var(--line);text-decoration:none;color:inherit;box-shadow:var(--shadow);transition:transform .2s,box-shadow .25s}.nc:hover{transform:translateY(-4px);box-shadow:0 18px 40px -18px rgba(27,39,34,.5)}
.nc-ph{position:relative;aspect-ratio:3/2;background:linear-gradient(135deg,var(--c,#0e6f66),#0b3b37);overflow:hidden}.nc-ph img{width:100%;height:100%;object-fit:cover;transition:transform .6s}.nc:hover .nc-ph img{transform:scale(1.06)}
.nc-n{position:absolute;left:10px;top:10px;width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:#fffdf8;color:#1b2722;font-family:Fraunces,Georgia,serif;font-size:19px;box-shadow:0 4px 14px rgba(0,0,0,.3)}
.nc-km{position:absolute;right:10px;bottom:10px;background:rgba(15,23,20,.72);backdrop-filter:blur(6px);color:#fff;font-size:12px;font-weight:700;padding:5px 10px;border-radius:999px}
.nc-tx{padding:12px 14px 14px;display:flex;flex-direction:column;gap:3px}.nc-tx small{color:var(--mute);font-size:12px;text-transform:uppercase;letter-spacing:.06em}.nc-tx small i{font-style:normal;color:var(--gold);font-weight:700}.nc-tx b{font-family:Fraunces,Georgia,serif;font-size:20px;line-height:1.15}.nc-tx>span{color:var(--mute);font-size:15px}
.nlist{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:18px}.nc.big .nc-tx b{font-size:23px}
.near-cta{margin:14px 0 0}.qf.nb{align-self:start}.mute{color:var(--mute);font-size:14px}
.basepin{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;font-size:20px;background:radial-gradient(circle at 30% 30%,#fff7e6,#e0ad55);border:3px solid #fff;box-shadow:0 0 0 4px rgba(224,173,85,.45),0 6px 16px rgba(0,0,0,.35)}
@media(max-width:820px){.ncs{grid-auto-columns:72%}}
.gmeta{color:var(--mute);font-size:14px;margin:0 0 14px}.gmeta a{color:var(--mute)}.toc{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:12px 16px;margin:18px 0}.toc summary{font-weight:700;cursor:pointer}.toc ol{margin:8px 0 0;padding-left:22px;columns:2;column-gap:28px}.toc li{margin:4px 0;break-inside:avoid}.toc a{text-decoration:none}@media(max-width:700px){.toc ol{columns:1}}.pl .body h2{scroll-margin-top:90px}.pl .body h3{font-family:Fraunces,Georgia,serif;font-size:21px;margin:22px 0 6px}.pl .body ul{padding-left:20px}.pl .body li{margin:6px 0}
@media (prefers-reduced-motion:reduce){.card,.nc,.btn{transition:none}.rv{opacity:1;transform:none}.hx-sl img{transition:none}.hx-sc{animation:none}}
section{padding:64px 0}
@media(max-width:980px){.exp{grid-template-columns:repeat(5,72%);overflow-x:auto;scroll-snap-type:x mandatory}.ex{scroll-snap-align:start;aspect-ratio:4/5}.mos{grid-template-columns:repeat(2,1fr);grid-auto-rows:180px}.mo.big{grid-column:span 2}.why3,.steps,.itc,.vids{grid-template-columns:1fr}.regs,.nm{grid-template-columns:repeat(2,1fr)}.sod-in,.mapcta-in,.pl2{grid-template-columns:1fr}.pl2-side .qf:first-child{position:static}.hx-in{bottom:110px}.hx-live{gap:8px;font-size:12px;bottom:18px}.hx-sc{display:none}.fab-map span{display:none}.gal2{grid-template-columns:repeat(2,1fr)}section{padding:48px 0}.itc{grid-auto-flow:column;grid-template-columns:none;grid-auto-columns:78%;overflow-x:auto}}
`;

function analytics() {
  return `<script>addEventListener('load',function(){setTimeout(function(){var g=document.createElement('script');g.async=1;g.src='https://www.googletagmanager.com/gtag/js?id=G-FJKJE77K4V';document.head.appendChild(g);window.dataLayer=window.dataLayer||[];window.gtag=function(){dataLayer.push(arguments)};gtag('js',new Date());gtag('config','G-FJKJE77K4V');
(function(c,l,a,r,i,t,y){c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y)})(window,document,"clarity","script","z4eqcmaic7");clarity("set","site","sumbasecrets");},1500)});</script>`;
}

const FLAG = { en: "gb", es: "es", id: "id", de: "de", fr: "fr", nl: "nl", it: "it", zh: "cn", ja: "jp", ko: "kr", ru: "ru", pt: "pt" };
const flag = (x, w = 22) => `<img class="fl" src="/flags/${FLAG[x]}.svg" width="${w}" height="${Math.round(w * .72)}" alt="" loading="lazy">`;
function langPicker(l, path, keepHash) {
  return `<details class="lp"><summary aria-label="${esc(D.ui[l].lang)}: ${esc(D.lname[l])}">${flag(l)}<b>${l.toUpperCase()}</b><i>▾</i></summary><div class="lp-m" role="menu">${L.map(x => `<a role="menuitem" hreflang="${x}" lang="${x}" href="/${x}${path}"${x === l ? ' class="on" aria-current="true"' : ""}${keepHash ? ` onclick="this.href=this.getAttribute('href')+location.hash"` : ""}>${flag(x, 26)}<span>${esc(D.lname[x])}</span></a>`).join("")}</div></details>`;
}
function cut60(t) { t = String(t); if (t.length <= 62) return t; let c = t.slice(0, 60); const i = c.lastIndexOf(" "); if (i > 30) c = c.slice(0, i); return c.replace(/[,;:·&\-\s]+$/, ""); }
function fixDesc(d, l) {
  d = String(d || "").replace(/\s+/g, " ").trim();
  if (d.length < 110) { const add = D.ui[l].hero_d; d = d + (d && !/[.!?。]$/.test(d) ? ". " : " ") + add; }
  if (d.length > 158) { let c = d.slice(0, 156); const i = c.lastIndexOf(" "); if (i > 100) c = c.slice(0, i); d = c.replace(/[,;:·\s]+$/, "") + "…"; }
  return d;
}
function page(l, path, o) {
  const u = D.ui[l];
  const alts = L.map(x => `<link rel="alternate" hreflang="${x}" href="${BASE}/${x}${path}">`).join("") + `<link rel="alternate" hreflang="x-default" href="${BASE}/en${path}">`;
  const nav = [["/secret-spots/", "★ " + u.secrets], ["/places/", u.places], ["/guides/", u.guides], ["/towns/", D.ui2[l].towns_t], ["/weather/", u.weather], ["/map/", "🗺️ " + u.map]]
    .map(([p, t]) => `<a href="/${l}${p}"${p === path ? ' class="on"' : ""}>${esc(t)}</a>`).join("") + `<a href="${TIMES}/${D.tl[l]}/">${esc(u.news)} ↗</a>`;
  const opts = L.map(x => `<option value="/${x}${path}"${x === l ? " selected" : ""}>${esc(D.lname[x])}</option>`).join("");
  const title = cut60(o.title ? (o.title.length <= 43 ? `${o.title} · Sumba Secrets` : o.title) : `Sumba Secrets: ${u.tag}`); o.desc = fixDesc(o.desc || u.hero_d, l);
  const ogimg = o.ogimgOwn || o.ogimg || (o.img ? img(o.img, 1280) : img("magnitude-6-1-earthquake-southwest-sumba", 1280));
  return `<!doctype html><html lang="${l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title><meta name="description" content="${esc(o.desc || u.hero_d)}">${o.robots ? `<meta name="robots" content="${o.robots}">` : ""}<link rel="canonical" href="${BASE}/${l}${path}">${alts}
<meta property="og:type" content="website"><meta property="og:site_name" content="Sumba Secrets"><meta property="og:title" content="${esc(o.title || "Sumba Secrets")}"><meta property="og:description" content="${esc(o.desc || u.hero_d)}"><meta property="og:image" content="${ogimg}"><meta property="og:url" content="${BASE}/${l}${path}"><meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#0e6f66"><link rel="manifest" href="/manifest.webmanifest"><link rel="apple-touch-icon" href="/icon.svg"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%230e6f66'/%3E%3Cpath d='M10 42c8-6 14-6 22 0s14 6 22 0' stroke='%23f7f2e8' stroke-width='5' fill='none' stroke-linecap='round'/%3E%3Ccircle cx='44' cy='22' r='7' fill='%23e0ad55'/%3E%3C/svg%3E">
<link rel="preconnect" href="https://i.ytimg.com">${o.preload ? `<link rel="preload" as="image" href="${o.preload}" fetchpriority="high"${o.preloadMedia ? ` media="${o.preloadMedia}"` : ""}>` : ""}<link href="/fonts.css" rel="stylesheet" media="print" onload="this.media='all'"><noscript><link href="/fonts.css" rel="stylesheet"></noscript><link rel="alternate" type="application/rss+xml" title="Sumba Secrets" href="/${l}/feed.xml">
${o.leaflet ? '<link rel="stylesheet" href="/lib/leaflet.css">' : ""}
<style>${CSS}</style>${o.ld ? [].concat(o.ld).map(x => `<script type="application/ld+json">${JSON.stringify(x)}</script>`).join("") : ""}${analytics()}</head><body${o.home && path === "/" ? ' class="home"' : ""}>
<div class="net"><div class="w"><b>${esc(u.network)}:</b><a href="${TIMES}/${D.tl[l]}/">The Sumba Times<span class="d"> · ${esc(u.times_d)}</span></a><a href="/${l}/"><b>Sumba Secrets</b><span class="d"> · ${esc(u.secrets_n)}</span></a></div></div>
<header class="top${o.home ? " over" : ""}" id="hdr"><div class="w"><a class="logo" href="/${l}/">Sumba <span>Secrets</span></a><nav class="main" aria-label="Main">${nav}</nav>
<a class="ico" href="/${l}/search/" aria-label="${esc(D.ui2[l].search_site)}" title="${esc(D.ui2[l].search_site)}">🔎</a><a class="ico" href="/${l}/saved/" aria-label="${esc(D.ui2[l].saved)}" title="${esc(D.ui2[l].saved)}">☆</a>${langPicker(l, path, false)}</div></header>
<main>${o.body}</main><nav class="bnav" aria-label="Mobile">${[["/", "🏝️", "Sumba"], ["/secret-spots/", "★", u.secrets], ["/guides/", "📖", u.guides], ["/map/", "🗺️", u.map], ["/saved/", "☆", D.ui2[l].saved]].map(([p, i, t]) => `<a href="/${l}${p}"${p === path ? ' class="on" aria-current="page"' : ""}><span>${i}</span><small>${esc(t)}</small></a>`).join("")}</nav><a class="fab-map" href="/${l}/map/" aria-label="${esc(u.map)}">🗺️ <span>${esc(u.map)}</span></a><button class="totop" aria-label="${esc(D.ui2[l].back_top)}" onclick="scrollTo({top:0,behavior:'smooth'})">↑</button>
${o.nonews ? "" : newsletterBox(l)}<footer><div class="w"><p>${D.towns.map(t => `<a href="/${l}/town/${t.s}/">${esc(t.n)}</a>`).join(" · ")} · <a href="https://happylowcost.com/" rel="noopener">✈ ${esc(D.ui2[l].flights)}</a> · <a href="/${l}/guide/itinerary-3-days/">${esc(D.ui2[l].itins)}</a> · <a href="/${l}/mamboro/">🏡 ${esc(NT(l).t)}</a></p><p><b>Sumba Secrets</b> · <a href="/${l}/about/">${esc(u.about)}</a> · <a href="${TIMES}/${D.tl[l]}/">The Sumba Times</a> · <a href="mailto:info@ecobeachcity.com">info@ecobeachcity.com</a></p>
<p>${Object.keys(D.rslug).map(r => `<a href="/${l}/region/${D.rslug[r]}/">${esc(D.ui[l].reg[r])}</a>`).join(" · ")}<br>${Object.keys(D.cslug).map(c => `<a href="/${l}/${D.cslug[c]}/">${esc(D.ui[l].cat[c])}</a>`).join(" · ")} · <a href="/${l}/secret-spots/">${esc(D.ui[l].secrets)}</a> · <a href="/map">${esc(D.ui2[l].fullmap)}</a></p><p>${L.map(x => `<a href="/${x}${path}" hreflang="${x}">${esc(D.lname[x])}</a>`).join(" · ")}</p><p>© ${new Date().getUTCFullYear()} Sumba Secrets. Published by Eco Beach City. Map data © OpenStreetMap contributors. Weather: Open-Meteo.</p></div></footer>
${o.leaflet ? '<script defer src="/lib/leaflet.js"></script>' : ""}${o.js ? `<script>addEventListener("DOMContentLoaded",function(){${o.js}})</script>` : ""}<script>${COMMONJS(l)}</script></body></html>`;
}

function mapJS(l, items, opts) {
  const u = D.ui[l];
  const mine = new Set(items.map(p => p.s));
  const pts = D.places.map(p => { const t = P(p, l); return { s: p.s, n: t.n, c: p.c, sec: p.sec, ll: p.ll, d: t.t.split(". ")[0] + ".", o: mine.has(p.s) ? 1 : 0 }; });
  return `(function(){var P=${JSON.stringify(pts)},C=${JSON.stringify(CAT_COLOR)},CAT=${JSON.stringify(u.cat)},SB=${JSON.stringify(u.secret_badge)},RM=${JSON.stringify(u.readmore)};
var mel=document.getElementById('map');if(!mel)return;function boot(){if(!window.L){setTimeout(boot,150);return}var m=L.map('map',{scrollWheelZoom:false}).setView(${JSON.stringify(opts.center || [-9.68, 119.75])},${opts.zoom || 9});
L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap &copy; CARTO'}).addTo(m);
var layers=[];P.forEach(function(p){var mk=L.circleMarker(p.ll,{radius:p.o?(p.sec?10:8):6,color:p.sec?'#e0ad55':'#fff',weight:p.sec?4:2,fillColor:C[p.c],fillOpacity:p.o?.95:.7}).addTo(m);if(p.o)mk.bringToFront&&setTimeout(function(){mk.bringToFront()},0);
mk.bindPopup('<b>'+p.n+'</b><br><small>'+CAT[p.c]+(p.sec?' · '+SB:'')+'</small><br>'+p.d+'<br><a href="/${l}/place/'+p.s+'/">'+RM+' →</a>');layers.push({p:p,mk:mk});});
${opts.base ? `L.marker(${JSON.stringify(NB.ll)},{zIndexOffset:2000,icon:L.divIcon({className:'',html:'<div class="basepin">🏡</div>',iconSize:[38,38],iconAnchor:[19,19]})}).addTo(m).bindPopup(${JSON.stringify('<b>' + esc(NT(l).base) + '</b><br><small>' + esc(NT(l).base_d) + '</small>')});` : ""}${opts.fit ? "var own=layers.filter(function(x){return x.p.o});if(own.length)m.fitBounds(L.featureGroup(own.map(function(x){return x.mk})).getBounds().pad(.08));" : ""}
document.querySelectorAll('.chip').forEach(function(b){b.onclick=function(){document.querySelectorAll('.chip').forEach(function(x){x.classList.remove('on')});b.classList.add('on');var f=b.dataset.f;
layers.forEach(function(x){var show=f==='all'||(f==='secret'?x.p.sec:x.p.c===f);if(show)x.mk.addTo(m);else m.removeLayer(x.mk)});
document.querySelectorAll('[data-cat]').forEach(function(el){el.style.display=(f==='all'||(f==='secret'?el.dataset.sec==='1':el.dataset.cat===f))?'':'none'})}});
}if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){io.disconnect();boot()}},{rootMargin:'400px'});io.observe(mel)}else boot();
})();`;
}

function chips(l) {
  const u = D.ui[l];
  return `<div class="chips">${["all", "secret", "beach", "waterfall", "village", "viewpoint", "culture"].map((f, i) => `<button class="chip${i ? "" : " on"}" data-f="${f}">${esc(u.cat[f])}</button>`).join("")}</div>`;
}

function wxJS(l, towns, full) {
  const u = D.ui[l];
  return `(function(){var T=${JSON.stringify(towns)},W=${JSON.stringify(D.wx[l])},U=${JSON.stringify({feels:u.feels,wind:u.wind,rain:u.rain,err:u.wx_err,days:u.days})};
function g(c){return c===0?0:c<=2?1:c===3?2:c<=48?3:c<=57?4:c<=67?5:c<=82?6:7}var I=['☀️','⛅','☁️','🌫️','🌦️','🌧️','🌦️','⛈️'];
var url='/api/wx';fetch(url).then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(d){d.forEach(function(x){var ti=T.filter(function(t){return t.s===x.s})[0];var el=ti&&document.getElementById('wx-'+x.s);if(!el||!x.current)return;var c=x.current,k=g(c.weather_code);
var h='<h3>'+ti.n+'</h3><div class="t">'+I[k]+' '+Math.round(c.temperature_2m)+'°</div><div class="s">'+W[k]+' · '+U.feels+' '+Math.round(c.apparent_temperature)+'° · '+U.wind+' '+Math.round(c.wind_speed_10m)+' km/h</div>';
${full ? `h+='<div class="days">'+x.daily.time.map(function(t,j){var dd=new Date(t+'T12:00:00');return '<div><b>'+U.days[dd.getDay()]+'</b>'+I[g(x.daily.weather_code[j])]+'<br>'+Math.round(x.daily.temperature_2m_max[j])+'° / '+Math.round(x.daily.temperature_2m_min[j])+'°<br><small>'+U.rain+' '+(x.daily.precipitation_probability_max[j]==null?'-':x.daily.precipitation_probability_max[j])+'%</small></div>'}).join('')+'</div>';` : ""}
el.innerHTML=h})}).catch(function(){T.forEach(function(t){var el=document.getElementById('wx-'+t.s);if(el){var bx=el.closest('.wx');(bx||el).style.display='none';var q=bx&&bx.closest('.qf');if(q)q.style.display='none'}})});})();`;
}

function wxBoxes(l, towns) { return `<div class="wx">${towns.map(t => `<div class="wxc" id="wx-${t.s}"><h3>${esc(t.n)}</h3><div class="s">${esc(D.ui[l].loading)}</div></div>`).join("")}</div>`; }

function newsBox(l) {
  const u = D.ui[l];
  return `<div class="news" id="news"><div class="s">${esc(u.loading)}</div></div><p><a href="${TIMES}/${D.tl[l]}/">${esc(u.allnews)} →</a></p>`;
}
function newsJS(l) {
  return `fetch('/api/news?l=${D.tl[l]}').then(function(r){return r.json()}).then(function(a){var e=document.getElementById('news');if(!a.length){e.innerHTML='';return}e.innerHTML=a.slice(0,5).map(function(n){var x=document.createElement('div');x.textContent=n.t;var t=x.innerHTML;x.textContent=n.d;return '<a class="n" href="'+n.u+'"><b>'+t+'</b><span>'+x.innerHTML+'</span></a>'}).join('')}).catch(function(){document.getElementById('news').innerHTML=''});`;
}

function ghero(g) {
  const pl = D.places.find(p => p.s === g.img);
  if (pl) { const ph = photos(pl)[0]; return { s: ph.s, b: ph.b, cr: [ph.a, ph.l, ph.f] }; }
  return { s: img(g.img, 640), b: img(g.img, 1280), cr: D.credits[g.img] };
}
function gtxt(g, l) { const t = Object.assign({}, g.en, g[l]); t.b = (t.b || "").replace(/\{l\}/g, l); return t; }
function guideCard(g, l) {
  const t = gtxt(g, l), h = ghero(g);
  return `<a class="card" href="/${l}/guide/${g.s}/" style="flex-direction:row"><div class="ph" style="flex:none;width:34%;aspect-ratio:auto;min-height:120px"><img src="${h.s}" alt="${esc(t.t)}" loading="lazy" onerror="this.remove()"></div><div class="tx"><h3>${esc(t.t)}</h3><p>${esc(t.d)}</p></div></a>`;
}

