async function apiTr(req, env) {
  // build-time translation proxy (Workers AI), protected by the TR_KEY secret
  if (!env.TR_KEY || req.headers.get("x-tr-key") !== env.TR_KEY || !env.AI) return new Response("Forbidden", { status: 403 });
  let b = {}; try { b = await req.json(); } catch (e) { return new Response("Bad request", { status: 400 }); }
  const r = await env.AI.run(b.model || "@cf/meta/llama-3.3-70b-instruct-fp8-fast", { messages: b.messages, max_tokens: b.max_tokens || 4096, temperature: b.temperature == null ? 0.2 : b.temperature });
  return Response.json({ result: r });
}
